            CREATE INDEX IF NOT EXISTS idx_readings_user_status_created
                ON readings (user_id, status, created_at DESC);

            CREATE INDEX IF NOT EXISTS idx_readings_completed_created
                ON readings (created_at DESC)
                WHERE status = 'COMPLETED';

            CREATE INDEX IF NOT EXISTS idx_cards_suit
                ON cards (suit);

            CREATE INDEX IF NOT EXISTS idx_cards_name_lower
                ON cards (LOWER(name));
